import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Как устроен Rimlink","description":"","frontmatter":{"pageId":"overview","contentRevision":5},"headers":[],"relativePath":"ru/overview.md","filePath":"ru/overview.md"}'),o={name:"ru/overview.md"};function l(d,a,n,s,h,p){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="как-устроен-rimlink" tabindex="-1">Как устроен Rimlink <a class="header-anchor" href="#как-устроен-rimlink" aria-label="Permalink to &quot;Как устроен Rimlink&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol class="flow-diagram" aria-label="Схема процесса"><li><strong>Домашняя карта</strong><span>Игрок симулирует и сохраняет свою колонию.</span></li><li><strong>Общий сервер</strong><span>Мир, права, кошельки и escrow.</span></li><li><strong>Live-хозяин</strong><span>Единственный исполнитель карты и writer сейва.</span></li><li><strong>Зеркало гостя</strong><span>Приказы своих/назначенных пешек, не второй сейв.</span></li></ol><p>Сервер хранит общий мир, сведения о поселениях, сейвы и сделки. Игрок развивает собственную колонию в своём темпе; чужое поселение видно на планете с индикатором присутствия. Сохранение передаётся серверу и возвращается при следующем входе.</p><p>Общение, подарки, рынок, аукционы и заказы соединяют колонии без общей симуляции. Визиты и асинхронные рейды используют копию карты. Live-режим передаёт гостю живое состояние хозяина; постоянная совместная колония дополнительно сохраняет разрешения на конкретных пешек.</p><h2 id="ownership" tabindex="-1">Кто симулирует мир и владеет сохранением? <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Кто симулирует мир и владеет сохранением? {#ownership}&quot;">​</a></h2><p>Слово «постоянный» относится к серверному миру и состоянию между подключениями, а не к фоновому проигрыванию каждой карты. Сервер хранит планету, игроков, поселения, экономику, очереди событий и принятые версии колонии. Домашнюю карту рассчитывает запущенная игра её владельца. Пока владелец вне игры, его поселенцы не добывают ресурсы и не переживают новые игровые дни.</p><table tabindex="0"><thead><tr><th>Режим</th><th>Кто считает карту</th><th>Что сохраняется</th></tr></thead><tbody><tr><td>Своя колония</td><td>Твой клиент</td><td>Принятый сервером домашний сейв</td></tr><tr><td>Обычный визит</td><td>Локальная копия чужой карты</td><td>Домашний сейв не заменяется копией</td></tr><tr><td>Асинхронный рейд</td><td>Игра защитника, когда он играет</td><td>Исход рейда и допустимые возвраты</td></tr><tr><td>Live / coop</td><td>Игра хозяина</td><td>Только хозяин пишет канонический сейв</td></tr></tbody></table><p>Две независимые колонии могут иметь разный игровой темп. Серверные сроки (например, истечение предложения) и игровые тики карты — разные часы. Поэтому офлайн-продавец может получить оплату на сервере, но его колония от этого не проживёт неделю.</p><h2 id="boundaries" tabindex="-1">Какие связи действительно общие? <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Какие связи действительно общие? {#boundaries}&quot;">​</a></h2><p>Чат и социальные отношения связывают игроков напрямую; товары и серебро проходят через серверное удержание и почту. Рейд и платное событие могут ждать следующего входа цели. Live нужен для одновременного управления, а постоянная совместная колония добавляет сохранённые разрешения на пешек хозяина.</p><p>Для выбора режима сначала ответь на вопрос: нужна независимая колония, разовая экскурсия, бой или управление хозяйскими колонистами? Дружба не выдаёт управление колонией; альянс не заменяет приглашение coop; цвет влияния не закрывает территорию. Эти системы пересекаются правилами, но не объединяют права.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Офлайн-колония не симулируется постоянно. Live не делает гостя владельцем сейва. Союз и слой влияния не дают права управлять чужой колонией.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./players/live">Live: живая карта</a></li><li><a href="./players/coop">Постоянная совместная колония</a></li><li><a href="./players/economy">Кошелёк, почта и рынок</a></li></ul>',17)])])}const m=t(o,[["render",l]]);export{u as __pageData,m as default};
